// === Tab: sketch.js ===
// 靈 © 2024-01-30 by Zaron Chen is licensed under CC BY-NC-SA 3.0. To view a copy of this license, visit https://creativecommons.org/licenses/by-nc-sa/3.0/
//
// Special thanks for inspiration:
//     https://gpfault.net/posts/webgl2-particles.txt.html

import { UPDATE_VERT, UPDATE_FRAG } from "./shaderSource.js"
import { RENDER_VERT, RENDER_FRAG } from "./shaderSource.js"
import Olon, { Data } from "https://cdn.jsdelivr.net/npm/olon@0.0.0/src/Olon.js"
import { random, floor, min } from "./tools.js"

const MAX_AMOUNT = 500000
const MIN_AGE = 1.01
const MAX_AGE = 2.15
const BIRTH_RATE = 0.5

const ol = Olon(1090, 690)
ol.enableCanvas2D()

let mousePos = [0, 0];
let mouseInside = true;
let spawnAtMouse = false;
let spawnFrames = 0;

let imgUrl = ["https://deckard.openprocessing.org/user454668/visual2922048/h84f63b755c76f35b95a2959a0b6d9849/ameenfahmy-JuesIryw53E-unsplash-2.jpg",
			  "https://deckard.openprocessing.org/user454668/visual2922048/h84f63b755c76f35b95a2959a0b6d9849/quino-al-BlMj6RYy3c0-unsplash.jpg",
			  "https://deckard.openprocessing.org/user454668/visual2922048/h84f63b755c76f35b95a2959a0b6d9849/luca-7m-Zigjxc8E-unsplash.jpg",
			 "https://deckard.openprocessing.org/user454668/visual2922048/h84f63b755c76f35b95a2959a0b6d9849/john-wiesenfeld-Ug6z9PCwr58-unsplash.jpg",
			 ""]
let urlIdx = 3; // 图像索引

// 使用 window 的 mousemove 事件，避免画布层级或加载时序问题
window.addEventListener('mousemove', (e) => {
    if (ol.mouseX >= -1 && ol.mouseX <= 1 &&
        ol.mouseY >= -1 && ol.mouseY <= 1) {
        mouseInside = true;
        mousePos[0] = ol.mouseX * 0.75;
        mousePos[1] = ol.mouseY * 0.75;
    } else {
        mouseInside = false;
    }
});

// 鼠标离开窗口时彻底关闭引力
window.addEventListener('click', () => {
    mouseInside = true;
    spawnAtMouse = true;
    spawnFrames = 24;   // 持续 2 帧，让一些粒子重生在鼠标处
    // console.log(spawnAtMouse);
});

ol.blend({
    sfactor: ol.SRC_ALPHA,
    dfactor: ol.ONE_MINUS_SRC_ALPHA,
})
ol.enableBlend();

// 异步加载图片并初始化
(async function init() {
    const url = imgUrl[urlIdx];
	 const img = await loadImageAsync(url);
    // console.log(`✅ 图片加载成功，尺寸：${img.width} x ${img.height}`);

    // 创建纹理（必须指定 width 和 height）
    const imageTex = ol.texture2D({
        data: img,
        width: img.width,
        height: img.height,
        iformat: ol.RGBA8,
        minFilter: ol.LINEAR,
        magFilter: ol.LINEAR,
        wrap: ol.CLAMP,
        flipY: true
    });

    // 测试像素读取（可选）
    // loadPixel(img);

    // 创建程序、buffer、VAO（原样）
    const TFV = ["vPosition", "vAge", "vLife", "vVel", "vForce", "vType", "vColor"];
    const updateProgram = ol.createProgram(UPDATE_VERT, UPDATE_FRAG, TFV);
    const renderProgram = ol.createProgram(RENDER_VERT, RENDER_FRAG);

    const aPosition = { name: "aPosition", unit: "f32", size: 2 };
    const aAge      = { name: "aAge",      unit: "f32", size: 1 };
    const aLife     = { name: "aLife",     unit: "f32", size: 1 };
    const aVel      = { name: "aVel",      unit: "f32", size: 2 };
    const aForce    = { name: "aForce",    unit: "f32", size: 2 };
    const aType     = { name: "aType",     unit: "f32", size: 1 };
    const aColor    = { name: "aColor",    unit: "f32", size: 3 };
    const attributes = [aPosition, aAge, aLife, aVel, aForce, aType, aColor];

    const particleData = [];
    for (let i = 0; i < MAX_AMOUNT; i++) {
        const life = random(MIN_AGE, MAX_AGE);
        particleData.push(0, 0);           // aPosition
        particleData.push(life + 1);       // aAge
        particleData.push(life);           // aLife
        particleData.push(0, 0);           // aVel
        particleData.push(0, 0);           // aForce
        particleData.push(0);              // aType
        particleData.push(0, 0, 0);        // aColor
    }
    const initData = Data(particleData);

    const buffer0 = ol.createBuffer(initData, ol.STREAM_DRAW);
    const buffer1 = ol.createBuffer(initData, ol.STREAM_DRAW);

    const vao0 = ol.createVAO(updateProgram, { buffer: buffer0, stride: 4 * 12, attributes });
    const vao1 = ol.createVAO(updateProgram, { buffer: buffer1, stride: 4 * 12, attributes });

    const buffers = [buffer0, buffer1];
    const vaos = [vao0, vao1];
    let [read, write] = [0, 1];
    let [lastTime, bornAmount] = [0, 0];

    ol.uniform("uRandom", [random() * 1024, random() * 1024]);

    // 启动渲染循环（此时纹理已就绪）
    ol.render(() => {
        const time = ol.frame / 60;
        const timeDelta = time - lastTime;
        lastTime = time;

        const nextAmount = floor(bornAmount + BIRTH_RATE * 1000);
        bornAmount = min(MAX_AMOUNT, nextAmount);

        ol.clearColor(0, 0, 0, 0.25);
        ol.clearDepth();

        if (spawnFrames > 0) {
            spawnFrames--;
            if (spawnFrames === 0) spawnAtMouse = false;
        }

        ol.use({ program: updateProgram }).run(() => {
            ol.transformFeedback(vaos[read], buffers[write], ol.POINTS, () => {
                ol.uniform("uImage", imageTex);   // 传入有效的纹理
                ol.uniform("uTimeDelta", timeDelta);
                ol.uniform("uTime", time);
                ol.uniform('uSpawnAtMouse', spawnAtMouse);
                ol.uniform('uMouse', mouseInside ? mousePos : [0, 0]);
                ol.uniform('uMouseActive', mouseInside ? 1.0 : 0.0);
                ol.points(0, bornAmount);
            });
        });

        ol.use({ program: renderProgram, VAO: vaos[write] }).run(() => ol.points(0, bornAmount));

        [read, write] = [write, read];
    });
})();

// 工具函数：异步加载图片
function loadImageAsync(url) {
    return new Promise((resolve, reject) => {
        var img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error(`图片加载失败: ${url}`));
        img.src = url;
    });
}

// 工具函数：读取像素并输出（可保留用于调试）
function loadPixel(img) {
    const canvas = document.createElement("canvas");
    canvas.width = img.width;
    canvas.height = img.height;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(img, 0, 0);

    const centerX = Math.floor(img.width / 2);
    const centerY = Math.floor(img.height / 2);
    const pixel = ctx.getImageData(centerX, centerY, 1, 1).data;
    console.log(`中心像素 (${centerX}, ${centerY}) RGBA: R=${pixel[0]}, G=${pixel[1]}, B=${pixel[2]}, A=${pixel[3]}`);
}

// === Tab: shaderSource.js ===
import * as Shox from "https://cdn.jsdelivr.net/npm/shox@1.1.0/src/Shox.js"

export const UPDATE_VERT = `
	precision mediump float;

	uniform float uTimeDelta;
	uniform float uTime;
	uniform vec2 uRandom;
	uniform vec2 uMouse;
	uniform float uMouseActive;
	uniform bool uSpawnAtMouse; // 允许保留 bool uniform
 uniform sampler2D uImage;

	in vec2 aPosition;
	in float aAge;
	in float aLife;
	in vec2 aVel;
	in vec2 aForce;
	in float aType;
 in vec3 aColor;


	// 顺序必须严格对应 JS 中的 TFV 数组
	out vec2 vPosition;
	out float vAge;
	out float vLife;
	out vec2 vVel;
	out vec2 vForce;
	out float vType; // 使用 float 传递标记
 out vec3 vColor;

	${Shox.noiseMath}
	${Shox.snoise3D}
	${Shox.hash}

void main() {
		vec2 noise = vec2(
			.5+.5*snoise(vec3(vec2(aPosition*10.+200.), uTime*.5)),
			.5+.5*snoise(vec3(vec2(aPosition*10.+100.), uTime*.5))
		);

		if (aAge >= aLife) {
  if (uSpawnAtMouse) {
        // 出生在鼠标位置，并加一点随机偏移避免完全重叠
        vec2 randOffset = hash22(vec2(gl_VertexID)) * 0.02 - 0.01;
        vPosition = uMouse + randOffset;
        vAge = 0.;
        vLife = aLife;
        vVel = vec2(0.0);  // 初始速度为零或微小随机值
		vForce = vec2(0.0);
  vType = 1.0;
    } else {
        // 原有的噪声出生逻辑
        ivec2 coord = ivec2(gl_VertexID%512, gl_VertexID/512);
        vec2 rand = hash22(vec2(coord));
        float posX = snoise(vec3(rand+vec2(uRandom.x), -uTime*.1+noise.x*.1));
        float posY = snoise(vec3(rand-vec2(uRandom.y),  uTime*.1+noise.y*.1));
        vPosition = .75*vec2(posX, posY);
        vAge = 0.;
        vLife = aLife;
        vVel = vPosition;
		vForce = vec2(0.0);
		vType = 0.0;
    }
	// 重生/初始化时赋予颜色值
	vec2 uv = vPosition / 0.75 * 0.5 + 0.5;
        vColor = texture(uImage, uv).rgb;
		} else {
			vec2 force = 3.*(2.*noise.rg-1.);
			vPosition = aPosition+aVel*uTimeDelta;
			vAge = aAge+uTimeDelta;
			vLife = aLife;
			vVel = .95*aVel+force*uTimeDelta*3.;
   vForce = force;
   vType = aType;
   vColor = aColor;   // 颜色保持不变
		}
	}

`

export const UPDATE_FRAG = `
	precision mediump float;
	in float vAge;
	void main() { discard; }
`

export const RENDER_VERT = `
	precision mediump float;
	uniform vec2 uMouse;
	uniform bool uSpawnAtMouse;

	in vec4 aPosition;
	in float aAge;
	in float aLife;
	in vec2 aForce;
	 in vec2 aVel;
	in float aType;
 in vec3 aColor;

	out vec4 vPosition;
	out float vAge;
	out float vLife;
	out vec2 vDebugMouse;
	out float vIsSpawning; // 修改：用 float 传递 uniform 状态
	out vec2 vDebugForce;
	out float vType;
 out vec3 vColor;

	void main() {
		vPosition = aPosition;
		vAge = aAge;
		vLife = aLife;
		gl_PointSize = 1.*(1.-aAge/aLife);
		gl_Position = aPosition;
  vDebugMouse = uMouse; // 3. 将鼠标值塞进信道
  vIsSpawning = uSpawnAtMouse ? 1.0 : 0.0;
  vDebugForce = aForce.xy;
  vType = aType; // *** 赋值 ***
  vColor = aColor;
	}
`

export const RENDER_FRAG = `
	precision mediump float;

	in float vAge;
	in float vLife;
	in vec2 vDebugMouse;
	in float vIsSpawning; // 接收 float
	in vec2 vDebugForce;
	in float vType;
 in vec3 vColor;

	out vec4 fragColor;

	void main() {

		if (vType > 0.5) {//指定交互重生粒子与自动重生粒子初始颜色
			fragColor = vec4(183./255., 105./255., 53./255., 3.-2.*vAge/vLife);
		} else {
			fragColor = vec4(20./255., 54./255., 66./255., 3.-2.*vAge/vLife);
		}
		// 统一指定颜色
		// fragColor = vec4(vAge/vLife*1.0, .0, 1.0, 1.0);//rgb
	  // fragColor = vec4(vType, 0.0, 1.0, 3.-2.*vAge/vLife);//rgb

		fragColor = vec4(vColor, 3.0 - 2.0 * vAge / vLife); // 读取底色

	}
`


// === Tab: tools.js ===
export const random = (min = 0, max = 1) => {
	return Math.random() * (max - min) + min
}

export const floor = (value) => {
	return Math.floor(value)
}

export const min = (value1, value2) => {
	return Math.min(value1, value2)
}

